                listed = self.srv.wf_review_event_response(
                    root, wave_id, "list", "probe", "variant-list",
                    finding_id="zero-variant",
                )
                self.assertTrue(
                    listed["data"]["chain_summary"]["zero-variant"]["terminal"],
                    listed,
                )

